ee:variables.ee:set-variable:
%dw 2.0
import SHA1 from dw::Crypto
import receivedIso from modules::EmailDates
output application/java
var headers = attributes.headers default {}
var messageIds = (headers filterObject ((value, key) -> lower(key as String) == "message-id")) pluck $
var messageId = if (isEmpty(messageIds)) ("imap-" ++ (attributes.id as String)) else (messageIds[0] as String)
var dateHeaders = (headers filterObject ((value, key) -> lower(key as String) == "date")) pluck $
// Gmail sends HTML bodies; keep readable text for the classifier and the record
var bodyText = trim((((payload.body default "") as String default "") replace /<[^>]+>/ with " " replace /&nbsp;/ with " " replace /\s+/ with " "))
// The classifier cannot open attachments, so it gets their names (e.g. "PO-7795-Cobalt-clean.pdf")
var attachmentNames = (payload.attachments default {}) pluck ((content, name) -> name as String)
var bodyWithAttachments = bodyText ++ (if (isEmpty(attachmentNames)) "" else "\n\n[Attachments: " ++ (attachmentNames joinBy ", ") ++ "]")
// Gmail gives "Display Name <address>"; Salesforce Email fields and contact matching need the bare address
var fromRaw = (attributes.fromAddresses[0] default "") as String
var fromAddress = if (fromRaw contains "<") ((fromRaw match /.*<([^>]+)>.*/)[1] default fromRaw) else fromRaw
---
{
    // SHA-1 of the Message-ID: same email, same key (duplicate protection), and URL-safe for the
    // Salesforce upsert path. A raw Message-ID ends in ".com", which Salesforce reads as a format suffix.
    messageKey: "gm-" ++ SHA1(messageId as Binary),
    // Original Message-ID, so the confirmation reply lands in the same Gmail thread
    messageId: messageId,
    from: lower(trim(fromAddress)),
    subject: attributes.subject default "",
    // From the Date header, which carries its own time zone (the connector's receivedDate has none)
    receivedIso: receivedIso(dateHeaders[0]),
    body: if (sizeOf(bodyWithAttachments) > 32000) bodyWithAttachments[0 to 31999] else bodyWithAttachments
}
